    manifest: m,
    stage,
    tasks,
    trace,
    checks: checkRows,
    snapshot,
    updatedAt,
    sourceInputSha256,
    issues,
    metrics,
    actualHead: input.actualHead,
    readyForImplementation: false,
    readyForArchive: false,
    nextAction:
