  } catch (error) {
    if (error.code !== 'ENOENT') throw error
    return false
  }
}
function ownedStatusTarget(manifest) {
  const own = `docs/engineering/directions/${manifest.id}/DIRECTION-STATUS.md`
  const legacyW01 =
    manifest.id === 'frade-standard-workflow' &&
